import type { Transition } from "motion/react";

/** Default clip-reveal easing for cartesian charts. */
export const DEFAULT_ANIMATION_EASING = "cubic-bezier(0.85, 0, 0.15, 1)";

export const DEFAULT_ANIMATION_DURATION_MS = 1100;

/** Default enter transition — matches the original line chart reveal. */
export const DEFAULT_CHART_ENTER_TRANSITION: Transition = {
  type: "tween",
  duration: DEFAULT_ANIMATION_DURATION_MS / 1000,
  ease: [0.85, 0, 0.15, 1],
};

/**
 * Clip-path width reveal must use tween — spring does not reliably animate SVG width.
 */
export function clipRevealTransition(enterTransition?: Transition): Transition {
  if (enterTransition?.type === "tween") {
    return {
      ...enterTransition,
      ease: enterTransition.ease ?? DEFAULT_CHART_ENTER_TRANSITION.ease,
    };
  }

  const duration =
    typeof enterTransition?.duration === "number"
      ? enterTransition.duration
      : DEFAULT_ANIMATION_DURATION_MS / 1000;

  return {
    type: "tween",
    duration,
    ease: DEFAULT_CHART_ENTER_TRANSITION.ease,
  };
}

// Copied from bklit-ui (packages/ui/src/charts/area-chart-loading.tsx) at commit 62c6768e8a5f74af27c2d9448ce11fce34141e30.
// MIT licence, Copyright (c) 2026 uixmat. The licence text is in LICENSE at the root of the charts folder.
"use client";

import { curveNatural } from "@visx/curve";
import { useMemo } from "react";
import { Area } from "./area";
import { AreaChart } from "./area-chart";
import type { Margin } from "./chart-context";
import type { LoadingStyle } from "./chart-phase";
import {
  DEFAULT_SKELETON_DATA_KEY,
  DEFAULT_SKELETON_POINT_COUNT,
  generateChartSkeletonData,
} from "./generate-chart-skeleton-data";
import { Grid } from "./grid";

const LOADING_DATA_KEY = DEFAULT_SKELETON_DATA_KEY;
const DEFAULT_LOADING_STROKE = "var(--foreground)";
const DEFAULT_LOADING_GRID_STROKE =
  "color-mix(in oklch, var(--chart-grid, var(--border)) 50%, transparent)";
const DEFAULT_LOADING_GRID_SHIMMER_STROKE =
  "color-mix(in oklch, var(--foreground) 68%, transparent)";
const DEFAULT_LOADING_STROKE_OPACITY = 0.5;

export interface AreaChartLoadingProps {
  /** Chart margins */
  margin?: Partial<Margin>;
  /** Stroke color for the animated loading segment. */
  stroke?: string;
  /** Stroke opacity for the animated loading segment. Default: 0.5 */
  strokeOpacity?: number;
  /** Grid line stroke (color and opacity via color-mix or oklch alpha). */
  gridStroke?: string;
  /** Shimmer band stroke (color and opacity via color-mix or oklch alpha). */
  gridShimmerStroke?: string;
  /** Animate a shimmer band across grid lines. Default: true */
  gridShimmer?: boolean;
  /** Shimmer band width in pixels. Default: 140 */
  gridShimmerLength?: number;
  /** Shimmer speed multiplier (higher = faster). Default: 1 */
  gridShimmerSpeed?: number;
  /** Match shimmer loop to the loading line pulse (cycle + inter-loop pause). */
  gridShimmerSync?: boolean;
  /** Loading animation: `"pulse"` (default traveling pulse) or `"sweep"` (a
   * diagonal shimmer across the skeleton area). Default: `"pulse"`. */
  loadingStyle?: LoadingStyle;
  /** Centered shimmer label text. Default: "Loading" */
  label?: string;
  /** Aspect ratio as "width / height". Default: "2 / 1" */
  aspectRatio?: string;
  /** Additional class name for the container */
  className?: string;
}

export function AreaChartLoading({
  margin,
  stroke = DEFAULT_LOADING_STROKE,
  strokeOpacity = DEFAULT_LOADING_STROKE_OPACITY,
  gridStroke = DEFAULT_LOADING_GRID_STROKE,
  gridShimmerStroke = DEFAULT_LOADING_GRID_SHIMMER_STROKE,
  gridShimmer = true,
  gridShimmerLength,
  gridShimmerSpeed,
  gridShimmerSync = false,
  loadingStyle = "pulse",
  label = "Loading",
  aspectRatio = "2 / 1",
  className = "",
}: AreaChartLoadingProps) {
  const data = useMemo(
    () =>
      generateChartSkeletonData({
        dataKey: DEFAULT_SKELETON_DATA_KEY,
        pointCount: DEFAULT_SKELETON_POINT_COUNT,
      }),
    []
  );

  return (
    <AreaChart
      animationDuration={0}
      aspectRatio={aspectRatio}
      className={className}
      data={data}
      loadingLabel={label}
      margin={margin}
      status="loading"
    >
      <Grid
        horizontal
        shimmer={loadingStyle === "sweep" ? false : gridShimmer}
        shimmerLength={gridShimmerLength}
        shimmerSpeed={gridShimmerSpeed}
        shimmerStroke={gridShimmerStroke}
        shimmerSync={gridShimmerSync}
        stroke={gridStroke}
      />
      <Area
        curve={curveNatural}
        dataKey={LOADING_DATA_KEY}
        fadeEdges={false}
        fill="transparent"
        fillOpacity={0}
        loading
        loadingStroke={stroke}
        loadingStrokeOpacity={strokeOpacity}
        loadingStyle={loadingStyle}
        showHighlight={false}
        showLine
        stroke="transparent"
        strokeWidth={2}
      />
    </AreaChart>
  );
}

export default AreaChartLoading;

// Copied from bklit-ui (packages/ui/src/charts/area-chart.tsx) at commit 62c6768e8a5f74af27c2d9448ce11fce34141e30.
// MIT licence, Copyright (c) 2026 uixmat. The licence text is in LICENSE at the root of the charts folder.
"use client";

import type { Transition } from "motion/react";
import {
  Children,
  type CSSProperties,
  isValidElement,
  type ReactNode,
  useCallback,
  useMemo,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";
import { Area, type AreaProps } from "./area";
import { AreaValueLabels } from "./area-value-labels";
import type { LineConfig, Margin } from "./chart-context";
import { ChartLoadingLabel } from "./chart-loading-label";
import { ParentSize } from "./chart-parent-size";
import {
  type ChartPhase,
  type ChartStatus,
  DEFAULT_CHART_STATUS,
  DEFAULT_Y_DOMAIN_TWEEN_MS,
  resolveRestingChartPhase,
} from "./chart-phase";
import { PatternArea } from "./pattern-area";
import { TimeSeriesChartInner } from "./time-series-chart-shell";

export interface AreaChartProps {
  /** Data array - each item should have a date field and numeric values */
  data: Record<string, unknown>[];
  /** Key in data for the x-axis (date). Default: "date" */
  xDataKey?: string;
  /** Chart margins */
  margin?: Partial<Margin>;
  /** Animation duration in milliseconds. Default: 1100 */
  animationDuration?: number;
  /** CSS easing for clip-reveal. Default: cubic-bezier(0.85, 0, 0.15, 1) */
  animationEasing?: string;
  /** Motion enter transition (spring or cubic-bezier tween). */
  enterTransition?: Transition;
  /** Signature of motion URL state — triggers reveal replay when it changes. */
  revealSignature?: string;
  /** Aspect ratio as "width / height". Default: "2 / 1" */
  aspectRatio?: string;
  /** Additional class name for the container */
  className?: string;
  /** Loading vs ready — drives chart phase and loading chrome. Default: `"ready"`. */
  status?: ChartStatus;
  /** Centered shimmer label while loading. */
  loadingLabel?: string;
  /** Animate y-domain over this duration (ms) on status transitions. Default: 500. */
  yDomainTweenDuration?: number;
  /** Animate y-domain when status or target domain changes. Default: true */
  yDomainTween?: boolean;
  /** Visible x-domain for brush zoom. */
  xDomain?: [Date, Date];
  /** Full dataset length for x-scale padding when `xDomain` is set. */
  xDomainSlotCount?: number;
  /** Tween y-domain when brush changes the visible x-range. Default: false */
  tweenYDomainOnXDomainChange?: boolean;
  /** Inline container styles (e.g. fixed height for brush strip). */
  style?: CSSProperties;
  /** Fires when the internal chart phase changes (e.g. OG capture readiness). */
  onPhaseChange?: (phase: ChartPhase) => void;
  /** Child components (Area, Grid, ChartTooltip, etc.) */
  children: ReactNode;
}

const DEFAULT_MARGIN: Margin = { top: 40, right: 40, bottom: 40, left: 40 };

function extractAreaConfigs(children: ReactNode): (LineConfig & AreaProps)[] {
  const configs: (LineConfig & AreaProps)[] = [];

  Children.forEach(children, (child) => {
    if (!isValidElement(child)) {
      return;
    }

    const childType = child.type as {
      displayName?: string;
      name?: string;
    };
    const componentName =
      typeof child.type === "function"
        ? childType.displayName || childType.name || ""
        : "";

    const props = child.props as AreaProps | undefined;
    const isPatternArea =
      componentName === "PatternArea" || child.type === PatternArea;
    // Overlays that carry a dataKey but are not series of their own.
    const isSeriesOverlay =
      componentName === "TrendLine" ||
      componentName === "LineSeriesTerminalMarker" ||
      componentName === "LineBackdrop";
    const isAreaComponent =
      componentName === "Area" ||
      child.type === Area ||
      (props &&
        typeof props.dataKey === "string" &&
        props.dataKey.length > 0 &&
        !isPatternArea &&
        !isSeriesOverlay);

    if (isAreaComponent && props?.dataKey) {
      configs.push({
        ...props,
        dataKey: props.dataKey,
        stroke: props.stroke || props.fill || "var(--chart-line-primary, var(--chart-1))",
        strokeWidth: props.strokeWidth || 2,
        yAxisId: props.yAxisId,
      });
    }
  });

  return configs;
}

interface ChartInnerProps {
  width: number;
  height: number;
  data: Record<string, unknown>[];
  xDataKey: string;
  margin: Margin;
  animationDuration: number;
  animationEasing?: string;
  enterTransition?: Transition;
  revealSignature?: string;
  chartStatus: ChartStatus;
  loadingLabel?: string;
  yDomainTweenDuration: number;
  yDomainTween: boolean;
  xDomain?: [Date, Date];
  xDomainSlotCount?: number;
  tweenYDomainOnXDomainChange?: boolean;
  children: ReactNode;
  containerRef: React.RefObject<HTMLDivElement | null>;
  onPhaseChange: (phase: ChartPhase) => void;
}

function ChartInner({
  width,
  height,
  data,
  xDataKey,
  margin,
  animationDuration,
  animationEasing,
  enterTransition,
  revealSignature,
  chartStatus,
  loadingLabel,
  yDomainTweenDuration,
  yDomainTween,
  xDomain,
  xDomainSlotCount,
  tweenYDomainOnXDomainChange,
  children,
  containerRef,
  onPhaseChange,
}: ChartInnerProps) {
  const lines = useMemo(() => extractAreaConfigs(children), [children]);

  return (
    <TimeSeriesChartInner
      animationDuration={animationDuration}
      animationEasing={animationEasing}
      chartStatus={chartStatus}
      clipPathId="chart-area-grow-clip"
      containerRef={containerRef}
      data={data}
      enterTransition={enterTransition}
      height={height}
      lines={lines}
      loadingLabel={loadingLabel}
      margin={margin}
      onPhaseChange={onPhaseChange}
      revealSignature={revealSignature}
      tweenYDomainOnXDomainChange={tweenYDomainOnXDomainChange}
      width={width}
      xDataKey={xDataKey}
      xDomain={xDomain}
      xDomainSlotCount={xDomainSlotCount}
      yDomainTween={yDomainTween}
      yDomainTweenDuration={yDomainTweenDuration}
    >
      {children}
      {/* Resolve labels together, above all fills and outside their edge masks. */}
      <AreaValueLabels series={lines} />
    </TimeSeriesChartInner>
  );
}

export function AreaChart({
  data,
  xDataKey = "date",
  margin: marginProp,
  animationDuration = 1100,
  animationEasing,
  enterTransition,
  revealSignature,
  aspectRatio = "2 / 1",
  className = "",
  status = DEFAULT_CHART_STATUS,
  loadingLabel,
  yDomainTweenDuration = DEFAULT_Y_DOMAIN_TWEEN_MS,
  yDomainTween = true,
  xDomain,
  xDomainSlotCount,
  tweenYDomainOnXDomainChange = false,
  style,
  onPhaseChange,
  children,
}: AreaChartProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const margin = { ...DEFAULT_MARGIN, ...marginProp };
  const [chartPhase, setChartPhase] = useState<ChartPhase>(() =>
    resolveRestingChartPhase(status)
  );
  const handlePhaseChange = useCallback(
    (phase: ChartPhase) => {
      setChartPhase(phase);
      onPhaseChange?.(phase);
    },
    [onPhaseChange]
  );

  const showLoadingLabel = Boolean(
    loadingLabel?.trim() &&
      (chartPhase === "loading" ||
        chartPhase === "exiting" ||
        chartPhase === "gridTweenReady" ||
        chartPhase === "revealingLoading")
  );

  return (
    <div
      className={cn("relative w-full", className)}
      ref={containerRef}
      style={{ aspectRatio, touchAction: "none", ...style }}
    >
      <ParentSize debounceTime={10}>
        {({ width, height }) => (
          <ChartInner
            animationDuration={animationDuration}
            animationEasing={animationEasing}
            chartStatus={status}
            containerRef={containerRef}
            data={data}
            enterTransition={enterTransition}
            height={height}
            loadingLabel={loadingLabel}
            margin={margin}
            onPhaseChange={handlePhaseChange}
            revealSignature={revealSignature}
            tweenYDomainOnXDomainChange={tweenYDomainOnXDomainChange}
            width={width}
            xDataKey={xDataKey}
            xDomain={xDomain}
            xDomainSlotCount={xDomainSlotCount}
            yDomainTween={yDomainTween}
            yDomainTweenDuration={yDomainTweenDuration}
          >
            {children}
          </ChartInner>
        )}
      </ParentSize>
      {showLoadingLabel ? (
        <ChartLoadingLabel
          exiting={chartPhase !== "loading"}
          text={loadingLabel}
        />
      ) : null}
    </div>
  );
}

export { Area, type AreaProps } from "./area";

export default AreaChart;

// Copied from bklit-ui (packages/ui/src/charts/area-gradient-defs.tsx) at commit 62c6768e8a5f74af27c2d9448ce11fce34141e30.
// MIT licence, Copyright (c) 2026 uixmat. The licence text is in LICENSE at the root of the charts folder.
import {
  type FadeEdges,
  fadeGradientStops,
  resolveFadeSides,
  viewportFadeGradientAttrs,
} from "./fade-edges";

interface AreaGradientDefsProps {
  gradientId: string;
  strokeGradientId: string;
  edgeMaskId: string;
  edgeGradientId: string;
  fill: string;
  fillOpacity: number;
  gradientToOpacity: number;
  /** 0–1: where the bottom stop sits (1 = full-height gradient). */
  gradientSpan?: number;
  resolvedStroke: string;
  isPatternFill: boolean;
  fadeEdges: FadeEdges;
  innerWidth: number;
  innerHeight: number;
}

export function AreaGradientDefs({
  gradientId,
  strokeGradientId,
  edgeMaskId,
  edgeGradientId,
  fill,
  fillOpacity,
  gradientToOpacity,
  gradientSpan = 1,
  resolvedStroke,
  isPatternFill,
  fadeEdges,
  innerWidth,
  innerHeight,
}: AreaGradientDefsProps) {
  const sides = resolveFadeSides(fadeEdges);
  // Stroke gradient mirrors the area's edge fade so the line doesn't pop in
  // past the faded fill. Skip emitting it when neither edge fades — the line
  // can then paint a solid stroke instead of an unnecessary url(#...) ref.
  const strokeStops = sides.any ? fadeGradientStops(sides) : null;
  const showEdgeMask = sides.any && !isPatternFill;
  const edgeStops = showEdgeMask ? fadeGradientStops(sides) : null;
  const span = Math.min(1, Math.max(0.01, gradientSpan));
  const midOffset = `${span * 100}%`;

  return (
    <defs>
      {isPatternFill ? null : (
        <linearGradient id={gradientId} x1="0%" x2="0%" y1="0%" y2="100%">
          <stop
            offset="0%"
            style={{ stopColor: fill, stopOpacity: fillOpacity }}
          />
          <stop
            offset={midOffset}
            style={{ stopColor: fill, stopOpacity: gradientToOpacity }}
          />
          {span < 1 ? (
            <stop
              offset="100%"
              style={{ stopColor: fill, stopOpacity: gradientToOpacity }}
            />
          ) : null}
        </linearGradient>
      )}

      {strokeStops ? (
        <linearGradient
          id={strokeGradientId}
          {...viewportFadeGradientAttrs(innerWidth)}
        >
          {strokeStops.map((stop) => (
            <stop
              key={stop.offset}
              offset={stop.offset}
              style={{ stopColor: resolvedStroke, stopOpacity: stop.opacity }}
            />
          ))}
        </linearGradient>
      ) : null}

      {edgeStops ? (
        <>
          <linearGradient
            id={edgeGradientId}
            {...viewportFadeGradientAttrs(innerWidth)}
          >
            {edgeStops.map((stop) => (
              <stop
                key={stop.offset}
                offset={stop.offset}
                style={{ stopColor: "white", stopOpacity: stop.opacity }}
              />
            ))}
          </linearGradient>
          <mask id={edgeMaskId}>
            <rect
              fill={`url(#${edgeGradientId})`}
              height={innerHeight}
              width={innerWidth}
              x="0"
              y="0"
            />
          </mask>
        </>
      ) : null}
    </defs>
  );
}

// Copied from bklit-ui (packages/ui/src/charts/area-value-label-layout.ts) at commit 62c6768e8a5f74af27c2d9448ce11fce34141e30.
// MIT licence, Copyright (c) 2026 uixmat. The licence text is in LICENSE at the root of the charts folder.
export interface AreaLabelBox {
  index: number;
  x: number;
  y: number;
  width: number;
  height: number;
}

/** Positions are box centers; all series share the same collision space. */
export function layoutAreaValueLabels(
  boxes: AreaLabelBox[],
  width: number,
  height: number
) {
  const placed: (AreaLabelBox & { source: number })[] = [];
  const padding = 4;
  const gap = 6;
  const visible = boxes
    .map((box, source) => ({ ...box, source }))
    .filter(
      (box) =>
        [box.index, box.x, box.y, box.width, box.height].every(
          Number.isFinite
        ) &&
        box.x >= 0 &&
        box.x <= width &&
        box.y >= 0 &&
        box.y <= height &&
        box.width > 0 &&
        box.height > 0 &&
        box.width + padding * 2 <= width &&
        box.height + padding * 2 <= height
    );
  const first = Math.min(...visible.map((box) => box.index));
  const last = Math.max(...visible.map((box) => box.index));
  const edge = (index: number) => (index === first || index === last ? 0 : 1);
  // Keep endpoints when possible; place higher series first, regardless of tree order.
  visible.sort(
    (a, b) => edge(a.index) - edge(b.index) || a.x - b.x || a.y - b.y
  );
  for (const box of visible) {
    const x = Math.max(
      padding + box.width / 2,
      Math.min(width - padding - box.width / 2, box.x)
    );
    const offset = box.height / 2 + gap;
    for (const y of [box.y - offset, box.y + offset]) {
      if (
        y - box.height / 2 < padding ||
        y + box.height / 2 > height - padding
      ) {
        continue;
      }
      const collision = placed.some(
        (other) =>
          Math.abs(x - other.x) < (box.width + other.width) / 2 + gap &&
          Math.abs(y - other.y) < (box.height + other.height) / 2 + gap
      );
      if (collision) {
        continue;
      }
      placed.push({ ...box, x, y });
      break;
    }
  }
  return placed;
}

/** Minimum is a preference; collision avoidance still takes priority. */
export function resolveAreaValueLabelCount(
  length: number,
  width: number,
  min = 2,
  max?: number
) {
  const minimum = Number.isFinite(min) ? Math.max(0, Math.floor(min)) : 2;
  const maximum =
    max != null && Number.isFinite(max) ? Math.max(0, Math.floor(max)) : length;
  return Math.min(
    length,
    maximum,
    Math.max(minimum, Math.floor(Math.max(0, width) / 48))
  );
}

export function resolveSharedAreaValueLabelCount(counts: number[]) {
  const enabledCounts = counts.filter((count) => count > 0);
  return enabledCounts.length ? Math.min(...enabledCounts) : 0;
}

/**
 * Exactly `count` indices (fewer only when `length < count`), spread evenly
 * across `[0, length - 1]` with both endpoints included.
 */
export function evenlySpacedLabelIndices(length: number, count: number) {
  const visibleCount = Math.min(Math.max(0, Math.floor(count)), length);
  if (visibleCount === 0) {
    return [];
  }
  if (visibleCount === 1) {
    return [0];
  }
  const lastIndex = length - 1;
  return Array.from({ length: visibleCount }, (_, index) =>
    Math.round((index * lastIndex) / (visibleCount - 1))
  );
}

// Copied from bklit-ui (packages/ui/src/charts/area-value-labels.tsx) at commit 62c6768e8a5f74af27c2d9448ce11fce34141e30.
// MIT licence, Copyright (c) 2026 uixmat. The licence text is in LICENSE at the root of the charts folder.
"use client";

import { useId, useLayoutEffect, useMemo, useRef } from "react";
import type { AreaProps } from "./area";
import {
  evenlySpacedLabelIndices,
  layoutAreaValueLabels,
  resolveAreaValueLabelCount,
  resolveSharedAreaValueLabelCount,
} from "./area-value-label-layout";
import { chartCssVars, useChartStable } from "./chart-context";
import { valueLabelFmt } from "./chart-formatters";
import {
  fadeGradientStops,
  resolveFadeSides,
  viewportFadeGradientAttrs,
} from "./fade-edges";

/** One final layer keeps later area fills from painting over earlier labels. */
export function AreaValueLabels({ series }: { series: AreaProps[] }) {
  const {
    data,
    xScale,
    xAccessor,
    yScale,
    yScales,
    innerWidth,
    innerHeight,
    chartPhase,
  } = useChartStable();
  const layerRef = useRef<SVGGElement>(null);
  const id = useId();
  const labels = useMemo(() => {
    if (!["revealing", "ready", "exitingReady"].includes(chartPhase)) {
      return [];
    }
    const visible = data
      .map((datum, index) => ({ datum, index, x: xScale(xAccessor(datum)) }))
      .filter(({ x }) => Number.isFinite(x) && x >= 0 && x <= innerWidth);
    const visibleSeries = series
      .map((area, seriesIndex) => ({
        area,
        seriesIndex,
        points: visible.filter(
          ({ datum }) =>
            typeof datum[area.dataKey] === "number" &&
            Number.isFinite(datum[area.dataKey])
        ),
      }))
      .filter(({ area }) => area.showValue);
    const counts = visibleSeries.map(({ area, points }) =>
      resolveAreaValueLabelCount(
        points.length,
        innerWidth,
        area.valueLabelMinCount,
        area.valueLabelMaxCount
      )
    );
    const sharedCount = resolveSharedAreaValueLabelCount(counts);
    return visibleSeries.flatMap(({ area, seriesIndex, points }, i) => {
      // Series that resolve to 0 (e.g. `valueLabelMaxCount={0}`) stay hidden;
      // the rest share the smallest non-zero count so labels line up.
      const count = Math.min(sharedCount, counts[i] ?? 0);
      if (count === 0) {
        return [];
      }
      const indices = evenlySpacedLabelIndices(points.length, count);
      return indices.flatMap((position) => {
        const point = position == null ? undefined : points[position];
        if (!point) {
          return [];
        }
        const { datum, index, x } = point;
        const value = datum[area.dataKey] as number;
        const scale = yScales[String(area.yAxisId ?? "left")] ?? yScale;
        const y = scale(value);
        if (!Number.isFinite(y)) {
          return [];
        }
        return [
          {
            index,
            seriesIndex,
            x,
            y,
            text: area.valueLabelFormatter?.(value) ?? valueLabelFmt(value),
          },
        ];
      });
    });
  }, [
    data,
    series,
    xScale,
    xAccessor,
    yScale,
    yScales,
    innerWidth,
    chartPhase,
  ]);

  useLayoutEffect(() => {
    const layer = layerRef.current;
    if (!layer) {
      return;
    }
    let active = true;
    const arrange = () => {
      if (!active) {
        return;
      }
      const elements = Array.from(layer.querySelectorAll("text"));
      const boxes = labels.map((label, index) => {
        const bounds = elements[index]?.getBBox();
        return {
          ...label,
          width: bounds?.width ?? 0,
          height: bounds?.height ?? 0,
        };
      });
      for (const element of elements) {
        element.style.visibility = "hidden";
      }
      for (const box of layoutAreaValueLabels(boxes, innerWidth, innerHeight)) {
        const element = elements[box.source];
        if (!element) {
          continue;
        }
        // Measure at the origin so font ascent, Persian digits and custom formats are respected.
        const bounds = element.getBBox();
        element.setAttribute(
          "transform",
          `translate(${box.x - bounds.x - bounds.width / 2}, ${box.y - bounds.y - bounds.height / 2})`
        );
        element.style.visibility = "visible";
      }
    };
    arrange();
    // Font loading changes Persian glyph widths; remeasure before deciding collisions.
    document.fonts.ready.then(arrange);
    document.fonts.addEventListener("loadingdone", arrange);
    return () => {
      active = false;
      document.fonts.removeEventListener("loadingdone", arrange);
    };
  }, [labels, innerWidth, innerHeight]);

  // Labels are opt-in: charts without `showValue` render no extra layer.
  if (!series.some((area) => area.showValue)) {
    return null;
  }

  return (
    <g pointerEvents="none" ref={layerRef}>
      <defs>
        {series.map(
          (area, index) =>
            area.fadeValueLabels && (
              <g key={area.dataKey}>
                <linearGradient
                  id={`${id}-${index}`}
                  {...viewportFadeGradientAttrs(innerWidth)}
                >
                  {fadeGradientStops(
                    resolveFadeSides(area.fadeEdges ?? false)
                  ).map((stop) => (
                    <stop
                      key={stop.offset}
                      offset={stop.offset}
                      stopColor="white"
                      stopOpacity={stop.opacity}
                    />
                  ))}
                </linearGradient>
                <mask
                  height={innerHeight}
                  id={`${id}-${index}-mask`}
                  maskUnits="userSpaceOnUse"
                  width={innerWidth}
                  x={0}
                  y={0}
                >
                  <rect
                    fill={`url(#${id}-${index})`}
                    height={innerHeight}
                    width={innerWidth}
                  />
                </mask>
              </g>
            )
        )}
      </defs>
      {labels.map((label) => {
        const area = series[label.seriesIndex];
        if (!area) {
          return null;
        }
        return (
          <g
            key={`${label.seriesIndex}-${label.index}`}
            mask={
              area.fadeValueLabels
                ? `url(#${id}-${label.seriesIndex}-mask)`
                : undefined
            }
          >
            <text
              className="font-medium text-[0.625rem]"
              fill={
                area.valueLabelColor ??
                area.stroke ??
                (area.fill?.startsWith("url(") ? undefined : area.fill) ??
                chartCssVars.linePrimary
              }
              style={{
                visibility: "hidden",
                paintOrder: "stroke",
                stroke: "var(--background)",
                strokeWidth: 3,
              }}
              x={0}
              y={0}
            >
              {label.text}
            </text>
          </g>
        );
      })}
    </g>
  );
}

