import { barDepthAndRise, barDepthMaxDepth } from "./bar-depth-geometry";
import {
  type BarValueLabelOrientation,
  type BarValueLabelPosition,
  getBarValueLabelLayout,
} from "./bar-value-label-layout";
import {
  chartCssVars,
