// CSS variable references for pie chart theming
export const pieCssVars = {
  background: "var(--chart-background, var(--muted))",
  foreground: "var(--chart-foreground, var(--muted-foreground))",
  foregroundMuted: "var(--chart-foreground-muted, color-mix(in oklch, var(--muted-foreground) 45%, transparent))",
  label: "var(--chart-label, var(--muted-foreground))",
  // Default slice colors from chart palette
  slice1: "var(--chart-1)",
  slice2: "var(--chart-2)",
  slice3: "var(--chart-3)",
  slice4: "var(--chart-4)",
