// Copied from bklit-ui (packages/ui/src/charts/responsive-chart-label-count.ts) at commit 62c6768e8a5f74af27c2d9448ce11fce34141e30.
// MIT licence, Copyright (c) 2026 uixmat. The licence text is in LICENSE at the root of the charts folder.
export interface ResponsiveChartLabelCount {
  base?: number;
  sm?: number;
  md?: number;
  lg?: number;
  xl?: number;
}

export type ChartLabelCount = number | ResponsiveChartLabelCount;

export function resolveResponsiveChartLabelCount(
  value: ChartLabelCount,
  containerWidth: number,
  fallback: number
): number {
  if (typeof value === "number") {
    return value;
  }

  const candidates = [
    [1280, value.xl],
    [1024, value.lg],
    [768, value.md],
    [640, value.sm],
    [0, value.base],
  ] as const;

  return (
    candidates.find(
      ([minWidth, count]) => containerWidth >= minWidth && count != null
    )?.[1] ?? fallback
  );
}

