  /** Stroke color. Default: var(--chart-segment-line, color-mix(in oklch, var(--foreground) 25%, transparent)) */
  stroke?: string;
  /** Stroke width. Default: 1 */
  strokeWidth?: number;
  /** Line style. Default: "dashed" */
  variant?: SegmentLineVariant;
}

function SegmentLine({
  x,
  stroke = chartCssVars.segmentLine,
  strokeWidth = 1,
  variant = "dashed",
  visible,
  innerHeight,
}: SegmentLineProps & {
  x: number;
  visible: boolean;
  innerHeight: number;
}) {
  // useId instead of a module counter: stable across SSR/hydration and no
  // mutation of module state during render.
  const gradientId = `segment-line-grad-${useId().replace(/:/g, "")}`;

  if (!visible) {
    return null;
  }

  if (variant === "gradient") {
    return (
      <g>
        <defs>
          <linearGradient id={gradientId} x1="0%" x2="0%" y1="0%" y2="100%">
            <stop offset="0%" style={{ stopColor: stroke, stopOpacity: 0 }} />
            <stop offset="10%" style={{ stopColor: stroke, stopOpacity: 1 }} />
            <stop offset="90%" style={{ stopColor: stroke, stopOpacity: 1 }} />
            <stop offset="100%" style={{ stopColor: stroke, stopOpacity: 0 }} />
          </linearGradient>
        </defs>
        <line
          stroke={`url(#${gradientId})`}
          strokeWidth={strokeWidth}
          x1={x}
          x2={x}
          y1={0}
          y2={innerHeight}
        />
