"use client";

import { useEffect, useState } from "react";

/**
 * Default grace period (ms) before a tooltip hides after hover ends. Bridges
 * gaps between adjacent targets (heatmap cells, choropleth features) so the
 * panel springs to the next target instead of fading out and back in.
 */
export const TOOLTIP_HIDE_DELAY_MS = 120;

/**
 * Delays showing (`showDelay`) and hiding (`hideDelay`) hover tooltip data.
 * Once visible, changes to another target apply immediately.
 *
 * Immediate updates are applied during render ("adjust state when props
 * change") and delayed ones from timers, so no state is set synchronously in
 * an effect (React Compiler `react-hooks/set-state-in-effect`).
 */
export function useDelayedTooltipData<T>(
  tooltipData: T | null,
  showDelay = 0,
  hideDelay = TOOLTIP_HIDE_DELAY_MS
): T | null {
  const [displayData, setDisplayData] = useState<T | null>(null);
  const [prevTooltipData, setPrevTooltipData] = useState<T | null>(null);

  // The tooltip counts as showing while it has data on screen (including
  // while a hide is pending).
  const isShowing = displayData !== null;

  if (prevTooltipData !== tooltipData) {
    setPrevTooltipData(tooltipData);
    if (tooltipData) {
      if (isShowing || showDelay === 0) {
        setDisplayData(tooltipData);
      }
    } else if (hideDelay === 0) {
      setDisplayData(null);
    }
  }

  useEffect(() => {
    if (tooltipData) {
      if (displayData === tooltipData) {
        return;
      }
      const showTimer = setTimeout(() => {
        setDisplayData(tooltipData);
      }, showDelay);
      return () => clearTimeout(showTimer);
    }

    if (displayData === null) {
      return;
    }
    const hideTimer = setTimeout(() => {
      setDisplayData(null);
    }, hideDelay);
    return () => clearTimeout(hideTimer);
  }, [tooltipData, displayData, showDelay, hideDelay]);

  return displayData;
}

// Copied from bklit-ui (packages/ui/src/charts/trend-line-utils.ts) at commit 62c6768e8a5f74af27c2d9448ce11fce34141e30.
// MIT licence, Copyright (c) 2026 uixmat. The licence text is in LICENSE at the root of the charts folder.
export interface TrendPoint {
  x: number;
  y: number;
}

export interface LinearRegression {
  slope: number;
  intercept: number;
}

/** Fitted segment endpoints in data space (regression x units → value). */
export interface TrendSegment {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
}

/**
 * Ordinary least-squares fit `y = slope * x + intercept`.
 * Non-finite points are skipped. Returns `null` for fewer than two finite
 * points or zero x-variance (vertical / single-x data).
 *
 * Mean-centered so large x values (epoch ms) don't lose precision.
 */
export function computeLinearRegression(
  points: TrendPoint[]
): LinearRegression | null {
  let n = 0;
  let sumX = 0;
  let sumY = 0;
  for (const { x, y } of points) {
    if (Number.isFinite(x) && Number.isFinite(y)) {
      n += 1;
      sumX += x;
      sumY += y;
    }
  }
  if (n < 2) {
    return null;
  }
  const meanX = sumX / n;
  const meanY = sumY / n;
  let covXY = 0;
  let varX = 0;
  for (const { x, y } of points) {
    if (Number.isFinite(x) && Number.isFinite(y)) {
      const dx = x - meanX;
      covXY += dx * (y - meanY);
      varX += dx * dx;
    }
  }
  if (varX === 0) {
    return null;
  }
  const slope = covXY / varX;
  return { slope, intercept: meanY - slope * meanX };
}

/** Regression line evaluated at the min / max finite x of `points`. */
export function computeTrendSegment(points: TrendPoint[]): TrendSegment | null {
  const fit = computeLinearRegression(points);
  if (!fit) {
    return null;
  }
  let minX = Number.POSITIVE_INFINITY;
  let maxX = Number.NEGATIVE_INFINITY;
  for (const { x, y } of points) {
    if (Number.isFinite(x) && Number.isFinite(y)) {
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
    }
  }
  return {
    x1: minX,
    y1: fit.slope * minX + fit.intercept,
    x2: maxX,
    y2: fit.slope * maxX + fit.intercept,
  };
}

/** Linear blend between two segments (`t` in 0…1). */
export function interpolateTrendSegment(
  from: TrendSegment,
  to: TrendSegment,
  t: number
): TrendSegment {
  return {
    x1: from.x1 + (to.x1 - from.x1) * t,
    y1: from.y1 + (to.y1 - from.y1) * t,
    x2: from.x2 + (to.x2 - from.x2) * t,
    y2: from.y2 + (to.y2 - from.y2) * t,
  };
}

