"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Variants,
} from "motion/react";
import { memo, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import {
  useChartPortalContainer,
  useChartStable,
  useSettledYScale,
  useYScale,
} from "./chart-context";
import { resolveReferenceDataRange } from "./reference-area-geometry";
import type { YAxisOrientation } from "./y-axis-scales";
import { normalizeYAxisId } from "./y-axis-scales";
import {
  resolveYAxisTickCount,
  Y_AXIS_DEFAULT_TICK_COUNT,
} from "./y-axis-ticks";

/** Vertical drift (px) of labels fading in / out on a y-domain change. */
const Y_AXIS_LABEL_SHIFT_PX = 8;
const Y_AXIS_LABEL_EASE_OUT = [0.23, 1, 0.32, 1] as const;
const Y_AXIS_LABEL_ENTER_S = 0.4;
const Y_AXIS_LABEL_EXIT_S = 0.25;
const Y_AXIS_LABEL_CLIP_BLEED_PX = 12;
/** Delay between consecutive entering labels (cascade). */
const Y_AXIS_LABEL_STAGGER_S = 0.05;

/**
 * Direction labels travel while the y-domain tweens: `-1` (up) when the
 * domain shrinks — values grow apart and rise — `1` (down) when it grows.
 */
type LabelDrift = -1 | 1;

interface LabelMotion {
  drift: LabelDrift;
  reducedMotion: boolean;
}

const labelVariants: Variants = {
  hidden: ({ drift }: LabelMotion) => ({
    opacity: 0,
    y: -drift * Y_AXIS_LABEL_SHIFT_PX,
  }),
  visible: { opacity: 1, y: 0 },
  exit: ({ drift, reducedMotion }: LabelMotion) => ({
    opacity: 0,
    y: drift * Y_AXIS_LABEL_SHIFT_PX,
    transition: {
      duration: reducedMotion ? 0 : Y_AXIS_LABEL_EXIT_S,
      ease: Y_AXIS_LABEL_EASE_OUT,
    },
  }),
};

export interface YAxisProps {
  /** Scale group id (Recharts `yAxisId`). Default: `"left"`. */
  yAxisId?: string | number;
  /** Which side of the chart to render labels. Default: `"left"`. */
  orientation?: YAxisOrientation;
  /**
   * Approximate tick count hint for `scale.ticks()` (d3). Actual label count may differ.
   * Clamped to {@link Y_AXIS_MIN_TICK_COUNT}–{@link Y_AXIS_MAX_TICK_COUNT}. Default: 5.
   */
  numTicks?: number;
  /** Format large numbers (e.g. 1000 as "1k"). Default: true */
  formatLargeNumbers?: boolean;
  /** Custom formatter for tick labels (e.g. USD). Overrides formatLargeNumbers when set. */
  formatValue?: (value: number) => string;
}

function formatLabel(
  value: number,
  formatLargeNumbers: boolean,
  formatValue?: (value: number) => string
): string {
  if (formatValue) {
    return formatValue(value);
  }
  if (formatLargeNumbers && value >= 1000) {
    // One decimal so 1500 reads "1.5k", not a second "2k".
    return `${Number((value / 1000).toFixed(1))}k`;
  }
  return String(value);
}

function resolveTickLabelColor(
  tickY: number,
  axisId: string,
  yScale: ReturnType<typeof useYScale>,
  referenceAreas: ReturnType<typeof useChartStable>["referenceAreas"]
): string | undefined {
  for (const area of referenceAreas) {
    if (!area.axisLabelColor) {
      continue;
    }
    if (normalizeYAxisId(area.yAxisId) !== axisId) {
      continue;
    }
    const [low, high] = resolveReferenceDataRange(
      area.y1,
      area.y2,
      yScale.domain() as [number, number]
    );
    const topPixel = yScale(high) ?? 0;
    const bottomPixel = yScale(low) ?? 0;
    const bandTop = Math.min(topPixel, bottomPixel);
    const bandBottom = Math.max(topPixel, bottomPixel);
    if (tickY >= bandTop && tickY <= bandBottom) {
      return area.axisLabelColor;
    }
  }
  return undefined;
}

export function YAxis(props: YAxisProps) {
  const { containerRef } = useChartStable();

  const container = useChartPortalContainer(containerRef);
  if (!container) {
    return null;
  }

  return <YAxisInner {...props} container={container} />;
}

const YAxisInner = memo(function YAxisInner({
  yAxisId,
  orientation = "left",
  numTicks = Y_AXIS_DEFAULT_TICK_COUNT,
  formatLargeNumbers = true,
  formatValue,
  container,
}: YAxisProps & { container: HTMLDivElement }) {
  const { margin, referenceAreas } = useChartStable();
  const yScale = useYScale(yAxisId);
  // Tick values come from the settled (target) domain so a y-domain tween
  // swaps one label set for the next once, instead of churning through every
  // intermediate tick set; positions still follow the live scale each frame.
  const settledYScale = useSettledYScale(yAxisId);
  const reducedMotion = useReducedMotion() ?? false;
  const isLeft = orientation === "left";
  const axisId = normalizeYAxisId(yAxisId);

  const [settledMin, settledMax] = settledYScale.domain() as [number, number];
  const settledSpan = settledMax - settledMin;
  const [prevSettledSpan, setPrevSettledSpan] = useState(settledSpan);
  const [drift, setDrift] = useState<LabelDrift>(-1);
  if (settledSpan !== prevSettledSpan) {
    setPrevSettledSpan(settledSpan);
    setDrift(settledSpan < prevSettledSpan ? -1 : 1);
  }

  const tickValues = useMemo(
    () => settledYScale.ticks(resolveYAxisTickCount(numTicks)),
    [settledYScale, numTicks]
  );

  const ticks = useMemo(() => {
    return tickValues.map((value) => {
      const y = (yScale(value) ?? 0) + margin.top;
      return {
        value,
        y,
        label: formatLabel(value, formatLargeNumbers, formatValue),
        labelColor: resolveTickLabelColor(
          y - margin.top,
          axisId,
          yScale,
          referenceAreas
        ),
      };
    });
  }, [
    tickValues,
    yScale,
    margin.top,
    formatLargeNumbers,
    formatValue,
    axisId,
    referenceAreas,
  ]);

  return createPortal(
    <div className="pointer-events-none absolute inset-0">
      <div
        className="absolute overflow-hidden"
        style={{
          // Clip labels tweening in from far off-scale, with room for a
          // half-height edge label when the chart margin is tight.
          top: -Y_AXIS_LABEL_CLIP_BLEED_PX,
          bottom: -Y_AXIS_LABEL_CLIP_BLEED_PX,
          ...(isLeft
            ? { left: 0, width: margin.left }
            : { right: 0, width: margin.right }),
        }}
      >
        <AnimatePresence
          custom={{ drift, reducedMotion } satisfies LabelMotion}
          initial={false}
        >
          {ticks.map((tick, index) => {
            // Cascade in the direction of travel: bottom-up while labels
            // rise, top-down while they fall.
            const cascadeIndex = drift < 0 ? index : ticks.length - 1 - index;
            return (
              <motion.div
                animate="visible"
                className="absolute flex h-0 items-center"
                custom={{ drift, reducedMotion } satisfies LabelMotion}
                exit="exit"
                initial="hidden"
                key={tick.value}
                style={{
                  top: tick.y + Y_AXIS_LABEL_CLIP_BLEED_PX,
                  ...(isLeft
                    ? { right: 0, justifyContent: "flex-end", paddingRight: 8 }
                    : {
                        left: 0,
                        justifyContent: "flex-start",
                        paddingLeft: 8,
                      }),
                }}
                transition={
                  reducedMotion
                    ? { duration: 0 }
                    : {
                        delay: cascadeIndex * Y_AXIS_LABEL_STAGGER_S,
                        duration: Y_AXIS_LABEL_ENTER_S,
                        ease: Y_AXIS_LABEL_EASE_OUT,
                      }
                }
                variants={labelVariants}
              >
                <span
                  className="whitespace-nowrap text-muted-foreground text-xs"
                  style={
                    tick.labelColor ? { color: tick.labelColor } : undefined
                  }
                >
                  {tick.label}
                </span>
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>
    </div>,
    container
  );
});

YAxis.displayName = "YAxis";

export default YAxis;

// Copied from bklit-ui (packages/ui/src/charts/y-domain-utils.ts) at commit 62c6768e8a5f74af27c2d9448ce11fce34141e30.
// MIT licence, Copyright (c) 2026 uixmat. The licence text is in LICENSE at the root of the charts folder.
import { scaleLinear } from "@visx/scale";
import type { LineConfig } from "./chart-context";
import { type ChartPhase, Y_DOMAIN_TWEEN_SKIP_THRESHOLD } from "./chart-phase";
import { groupLinesByYAxisId, normalizeYAxisId } from "./y-axis-scales";

export type YDomain = [number, number];

export interface NumericExtents {
  minValue: number;
  maxValue: number;
}

/** Min / max over every numeric `dataKeys` value. `{ 0, 100 }` when none are numeric. */
export function collectNumericExtents(
  data: Record<string, unknown>[],
  dataKeys: string[]
): NumericExtents {
  let minValue = Number.POSITIVE_INFINITY;
  let maxValue = Number.NEGATIVE_INFINITY;

  for (const d of data) {
    for (const key of dataKeys) {
      const value = d[key];
      if (typeof value === "number") {
        if (value < minValue) {
          minValue = value;
        }
        if (value > maxValue) {
          maxValue = value;
        }
      }
    }
  }

  if (minValue === Number.POSITIVE_INFINITY) {
    return { minValue: 0, maxValue: 100 };
  }

  return { minValue, maxValue };
}

/**
 * Line / area y-domain: zero-anchored while every value is >= 0, padded
 * min..max once any value is negative.
 */
export function resolveTimeSeriesYDomain(
  data: Record<string, unknown>[],
  dataKeys: string[],
  yScaleDomainMax: number | undefined
): YDomain {
  if (yScaleDomainMax != null && yScaleDomainMax > 0) {
    return [0, yScaleDomainMax * 1.1];
  }

  const { minValue, maxValue } = collectNumericExtents(data, dataKeys);

  if (minValue >= 0) {
    const top = maxValue <= 0 ? 100 : maxValue * 1.1;
    return [0, top];
  }

  const padding = (maxValue - minValue) * 0.05 || 1;
  return [minValue - padding, maxValue + padding];
}

/**
 * Value extents for bar series. Stacked bars use the running totals (always
 * including the zero baseline) so the domain reaches every segment end;
 * grouped bars use the individual values.
 */
export function collectBarValueExtents(
  data: Record<string, unknown>[],
  dataKeys: string[],
  stacked: boolean
): NumericExtents {
  if (!stacked) {
    return collectNumericExtents(data, dataKeys);
  }
  let minValue = 0;
  let maxValue = 0;
  for (const d of data) {
    let sum = 0;
    for (const key of dataKeys) {
      const value = d[key];
      if (typeof value === "number") {
        sum += value;
        minValue = Math.min(minValue, sum);
        maxValue = Math.max(maxValue, sum);
      }
    }
  }
  return { minValue, maxValue };
}

/**
 * Bar value-axis domain. Bars grow from zero, so the domain always includes
 * 0: `[0, max * 1.1]` while every value is >= 0 (falls back to `[0, 110]`
 * when there is no positive value), and a padded min..max stretched to
 * include zero once any value is negative.
 */
export function resolveBarValueDomain({
  minValue,
  maxValue,
}: NumericExtents): YDomain {
  if (minValue >= 0) {
    return [0, (maxValue > 0 ? maxValue : 100) * 1.1];
  }

  const padding = (maxValue - minValue) * 0.05 || 1;
  return [Math.min(0, minValue - padding), Math.max(0, maxValue + padding)];
}

/** Apply visx `nice()` to raw domain endpoints for stable grid ticks. */
export function niceYDomain(domain: YDomain): YDomain {
  const scale = scaleLinear({ domain, range: [0, 1], nice: true });
  const niceDomain = scale.domain();
  return [niceDomain[0] ?? domain[0], niceDomain[1] ?? domain[1]];
}

/**
 * Skip Y tween when both endpoints move less than the threshold relative to span.
 * When in doubt callers should tween — beauty wins over micro-optimization.
 */
export function shouldTweenYDomain(from: YDomain, to: YDomain): boolean {
  const span = Math.max(
    Math.abs(to[1] - to[0]),
    Math.abs(from[1] - from[0]),
    1
  );
  const deltaMin = Math.abs(to[0] - from[0]) / span;
  const deltaMax = Math.abs(to[1] - from[1]) / span;
  return (
    deltaMin >= Y_DOMAIN_TWEEN_SKIP_THRESHOLD ||
    deltaMax >= Y_DOMAIN_TWEEN_SKIP_THRESHOLD
  );
}

/** Phases where the chart shows loading chrome (shimmer, pulse, label). */
export function isLoadingChromePhase(phase: ChartPhase): boolean {
  return phase === "loading" || phase === "revealingLoading";
}

/** Phases where grid lines use loading stroke styling (muted / dashed chrome). */
export function isLoadingGridChromePhase(phase: ChartPhase): boolean {
  return (
    phase === "loading" || phase === "exiting" || phase === "gridTweenLoading"
  );
}

/** Phases where Y-domain tween runs after the series has exited. */
export function isYDomainTweenPhase(phase: ChartPhase): boolean {
  return phase === "gridTweenLoading" || phase === "gridTweenReady";
}

/** Phases where {@link ReferenceArea} bands are shown (fade in/out on transitions). */
export function isReferenceAreaVisiblePhase(phase: ChartPhase): boolean {
  return (
    phase === "ready" || phase === "revealing" || phase === "gridTweenReady"
  );
}

export function resolveAnimatedYDestinationDomains(
  chartPhase: ChartPhase,
  skeletonByAxis: Record<string, YDomain>,
  targetByAxis: Record<string, YDomain>
): Record<string, YDomain> {
  switch (chartPhase) {
    case "loading":
    case "exiting":
    case "gridTweenLoading":
      return skeletonByAxis;
    case "exitingReady":
    case "gridTweenReady":
    case "revealing":
    case "ready":
      return targetByAxis;
    default:
      return targetByAxis;
  }
}

export function computeYDomainsByAxis({
  lines,
  resolveDomain,
  extraKeysByAxis,
}: {
  lines: LineConfig[];
  resolveDomain: (dataKeys: string[]) => YDomain;
  /**
   * Additional value keys per axis that extend the domain without being
   * series (e.g. `<Band>` upper/lower keys). Axes with only extra keys still
   * get a domain.
   */
  extraKeysByAxis?: Record<string, string[]>;
}): Record<string, YDomain> {
  const keysByAxis = new Map<string, string[]>();
  for (const [axisId, axisLines] of groupLinesByYAxisId(lines)) {
    keysByAxis.set(
      normalizeYAxisId(axisId),
      axisLines.map((line) => line.dataKey)
    );
  }
  for (const [axisId, extraKeys] of Object.entries(extraKeysByAxis ?? {})) {
    const id = normalizeYAxisId(axisId);
    const keys = keysByAxis.get(id) ?? [];
    keysByAxis.set(id, [
      ...keys,
      ...extraKeys.filter((key) => !keys.includes(key)),
    ]);
  }

  const domains: Record<string, YDomain> = {};
  for (const [axisId, dataKeys] of keysByAxis) {
    domains[axisId] = niceYDomain(resolveDomain(dataKeys));
  }

  if (!domains.left) {
    domains.left = niceYDomain([0, 100]);
  }

  return domains;
}

/** Merge domain maps, normalizing axis ids to strings. */
export function mergeYDomainRecords(
  ...records: Record<string, YDomain>[]
): Record<string, YDomain> {
  const merged: Record<string, YDomain> = {};
  for (const record of records) {
    for (const [axisId, domain] of Object.entries(record)) {
      merged[normalizeYAxisId(axisId)] = domain;
    }
  }
  return merged;
}

export function domainsEqual(
  left: Record<string, YDomain>,
  right: Record<string, YDomain>
): boolean {
  const leftKeys = Object.keys(left);
  const rightKeys = Object.keys(right);
  if (leftKeys.length !== rightKeys.length) {
    return false;
  }

  for (const axisId of leftKeys) {
    const from = left[axisId];
    const to = right[axisId];
    if (!(from && to) || from[0] !== to[0] || from[1] !== to[1]) {
      return false;
    }
  }

  return true;
}
